                <td><span className={`badge ${s.status}`}><span aria-hidden="true">{STATUS_ICON[s.status]}</span> {STATUS_LABEL[s.status]}</span></td>
                <td className="num">{s.latency === null ? '—' : `${s.latency} ms`}</td>
                <td>{ago(s.checkedAt, now)}</td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </section>
  );
}

