*{box-sizing:border-box}
body{margin:0;background:#f3f4f6;color:#111827;font:16px/1.5 system-ui,"Noto Sans TC","Microsoft JhengHei",sans-serif;overflow-x:hidden}
.page{max-width:1200px;margin:0 auto;padding:16px}
h1{font-size:1.6rem;margin:8px 0 16px}
h2{font-size:1.2rem;margin:0}
h3{font-size:1rem;margin:16px 0 8px}
p{margin:4px 0}
.muted{color:#4b5563;font-size:.9rem}
.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}
:focus-visible{outline:3px solid #1d4ed8;outline-offset:2px}
.panel{background:#fff;border:1px solid #d1d5db;border-radius:8px;padding:16px;margin-top:16px;min-width:0}
.row{display:flex;flex-wrap:wrap;gap:12px;align-items:center;justify-content:space-between}
.cards{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(4,1fr);gap:12px}
.card{background:#fff;border:1px solid #d1d5db;border-radius:8px;padding:16px;min-width:0}
.card h3{margin:0;color:#374151;font-size:.95rem}
.big{font-size:1.7rem;font-weight:700;margin:4px 0}
.delta{font-size:.9rem;font-weight:600}
.delta.good{color:#15803d}.delta.bad{color:#b91c1c}
.delta .muted{font-weight:400}
.skeleton{background:linear-gradient(90deg,#e5e7eb,#f3f4f6,#e5e7eb);min-height:100px;border-radius:8px}
.skeleton.block{min-height:200px;margin-top:16px}
.loading-msg{font-weight:600;margin-bottom:12px}
.notice{text-align:center;padding:40px 16px}
.notice h2{margin-bottom:8px}
.btn{display:inline-block;background:#fff;color:#111827;border:1px solid #6b7280;border-radius:6px;padding:8px 14px;font:inherit;cursor:pointer;text-decoration:none;min-height:40px}
.btn.primary{background:#1d4ed8;border-color:#1d4ed8;color:#fff;margin-top:12px}
.seg{display:inline-flex}
.seg button{font:inherit;padding:6px 12px;border:1px solid #6b7280;background:#fff;color:#111827;cursor:pointer;min-height:40px;margin-left:-1px}
.seg button:first-child{border-radius:6px 0 0 6px;margin-left:0}
.seg button:last-child{border-radius:0 6px 6px 0}
.seg button[aria-pressed=true]{background:#1d4ed8;border-color:#1d4ed8;color:#fff}
.chart{margin:12px 0 0}
.chart figcaption{font-weight:600;font-size:.95rem}
.chart svg{width:100%;height:auto;display:block}
.data-details{margin-top:12px}
.data-details summary{cursor:pointer;font-weight:600;padding:6px 0}
.table-scroll{max-height:280px;overflow:auto;margin-top:8px}
table{width:100%;border-collapse:collapse;font-size:.95rem}
th,td{text-align:left;padding:8px;border-bottom:1px solid #e5e7eb;vertical-align:middle;overflow-wrap:anywhere}
thead th{background:#f9fafb}
.num{text-align:right}
th.name{font-weight:600}
.field{display:flex;align-items:center;gap:8px}
select{font:inherit;padding:6px 8px;min-height:40px;border:1px solid #6b7280;border-radius:6px;background:#fff;color:#111827}
.sort{font:inherit;font-weight:700;background:none;border:0;padding:0;cursor:pointer;color:inherit;text-align:left}
.badge{display:inline-block;padding:2px 8px;border-radius:999px;font-weight:600;font-size:.85rem;white-space:nowrap}
.badge.ok{background:#dcfce7;color:#14532d}
.badge.degraded{background:#fef3c7;color:#78350f}
.badge.down{background:#fee2e2;color:#7f1d1d}
.alerts{list-style:none;margin:0;padding:0;display:grid;gap:8px}
.alert{display:flex;gap:12px;justify-content:space-between;align-items:flex-start;border:1px solid #e5e7eb;border-radius:6px;padding:10px 12px}
.alert>div{min-width:0;overflow-wrap:anywhere}
.alert .btn{flex:none}
.sev{display:inline-block;padding:1px 8px;border-radius:4px;font-size:.8rem;font-weight:700}
.sev.critical{background:#991b1b;color:#fff}
.sev.warning{background:#fef3c7;color:#78350f}
.sev.info{background:#dbeafe;color:#1e3a8a}
@media (max-width:900px){.cards{grid-template-columns:repeat(2,1fr)}}
@media (max-width:480px){
  .page{padding:12px}
  .cards{gap:8px}
  .card{padding:12px}
  .big{font-size:1.35rem}
  .panel{padding:12px}
  th,td{padding:6px 4px;font-size:.85rem}
  .alert{flex-direction:column}
}

